P/Invoke for `CryptUnprotectData` (crypt32). Optional entropy = `IntPtr.Zero` when null; else pointer to `DATA_BLOB`. `pDataOut.pbData` freed with `LocalFree`. Prefer `ProtectedData.Unprotect` if `System.Security.Cryptography.ProtectedData` is enough.

```csharp
using System;
using System.ComponentModel;
using System.Runtime.InteropServices;

internal static class Crypt32
{
    public const uint CRYPTPROTECT_UI_FORBIDDEN = 0x01;
    public const uint CRYPTPROTECT_VERIFY_PROTECTION = 0x40;

    [StructLayout(LayoutKind.Sequential)]
    public struct DATA_BLOB
    {
        public uint cbData;
        public IntPtr pbData;
    }

    [DllImport("crypt32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    [return: MarshalAs(UnmanagedType.Bool)]
    public static extern bool CryptUnprotectData(
        ref DATA_BLOB pDataIn,
        IntPtr ppszDataDescr,       // LPWSTR*; IntPtr.Zero to ignore description
        IntPtr pOptionalEntropy,    // DATA_BLOB*; IntPtr.Zero if no entropy
        IntPtr pvReserved,          // must be IntPtr.Zero
        IntPtr pPromptStruct,       // CRYPTPROTECT_PROMPTSTRUCT*; usually Zero
        uint dwFlags,
        out DATA_BLOB pDataOut);

    [DllImport("kernel32.dll")]
    private static extern IntPtr LocalFree(IntPtr hMem);

    /// <summary>
    /// Decrypt DPAPI blob. Pass <paramref name="optionalEntropy"/> only if
    /// CryptProtectData used the same entropy; otherwise omit (null).
    /// </summary>
    public static byte[] Unprotect(
        byte[] cipher,
        byte[] optionalEntropy = null,
        uint flags = CRYPTPROTECT_UI_FORBIDDEN)
    {
        if (cipher == null || cipher.Length == 0)
            throw new ArgumentException("Ciphertext required.", nameof(cipher));

        DATA_BLOB input = default;
        DATA_BLOB output = default;
        DATA_BLOB entropy = default;
        IntPtr entropyPtr = IntPtr.Zero;

        try
        {
            input = ToBlob(cipher);

            if (optionalEntropy != null && optionalEntropy.Length > 0)
            {
                entropy = ToBlob(optionalEntropy);
                entropyPtr = Marshal.AllocHGlobal(Marshal.SizeOf<DATA_BLOB>());
                Marshal.StructureToPtr(entropy, entropyPtr, fDeleteOld: false);
            }

            if (!CryptUnprotectData(
                    ref input,
                    IntPtr.Zero,
                    entropyPtr,          // Zero == no entropy
                    IntPtr.Zero,
                    IntPtr.Zero,
                    flags,
                    out output))
            {
                throw new Win32Exception(Marshal.GetLastWin32Error());
            }

            if (output.pbData == IntPtr.Zero || output.cbData == 0)
                return Array.Empty<byte>();

            var plain = new byte[output.cbData];
            Marshal.Copy(output.pbData, plain, 0, (int)output.cbData);
            return plain;
        }
        finally
        {
            FreeBlob(ref input, localAlloc: false);
            FreeBlob(ref entropy, localAlloc: false);
            if (entropyPtr != IntPtr.Zero)
                Marshal.FreeHGlobal(entropyPtr);
            FreeBlob(ref output, localAlloc: true); // crypt32 used LocalAlloc
        }
    }

    private static DATA_BLOB ToBlob(byte[] data)
    {
        var blob = new DATA_BLOB
        {
            cbData = (uint)data.Length,
            pbData = Marshal.AllocHGlobal(data.Length)
        };
        Marshal.Copy(data, 0, blob.pbData, data.Length);
        return blob;
    }

    private static void FreeBlob(ref DATA_BLOB blob, bool localAlloc)
    {
        if (blob.pbData == IntPtr.Zero)
            return;

        try
        {
            // Best-effort wipe of native buffer
            int n = (int)blob.cbData;
            if (n > 0)
            {
                var zeros = new byte[n];
                Marshal.Copy(zeros, 0, blob.pbData, n);
            }
        }
        finally
        {
            if (localAlloc)
                LocalFree(blob.pbData);
            else
                Marshal.FreeHGlobal(blob.pbData);

            blob.pbData = IntPtr.Zero;
            blob.cbData = 0;
        }
    }
}
```

Call:

```csharp
byte[] plain = Crypt32.Unprotect(cipher);                    // no entropy
byte[] plain2 = Crypt32.Unprotect(cipher, extraEntropy);     // same entropy as Protect
```

Notes:
- Entropy must match `CryptProtectData` exactly (byte-for-byte). Null entropy ≠ empty entropy if the protector used one.
- Description (`ppszDataDescr`) skipped via `IntPtr.Zero`. If you need it, pass `out IntPtr` and `Marshal.PtrToStringUni` then `LocalFree`.
- Output buffer is `LocalAlloc`'d by crypt32 → `LocalFree`, not `FreeHGlobal`.
- Same user / same machine as the protector, unless `CRYPTPROTECT_LOCAL_MACHINE` was used on protect.
- Managed equivalent: `ProtectedData.Unprotect(cipher, entropy, DataProtectionScope.CurrentUser)`.

Standard Keychain lookup via Security.framework: `SecItemCopyMatching` on `kSecClassGenericPassword`, keyed by service + account.

Swift
```swift
import Foundation
import Security

enum KeychainReadError: Error {
    case itemNotFound
    case unexpectedData
    case status(OSStatus)
}

/// Reads a generic-password item. Returns UTF-8 password string.
func keychainGenericPassword(service: String, account: String) throws -> String {
    let query: [String: Any] = [
        kSecClass as String: kSecClassGenericPassword,
        kSecAttrService as String: service,
        kSecAttrAccount as String: account,
        kSecReturnData as String: true,
        kSecMatchLimit as String: kSecMatchLimitOne
    ]

    var item: CFTypeRef?
    let status = SecItemCopyMatching(query as CFDictionary, &item)

    switch status {
    case errSecSuccess:
        guard let data = item as? Data,
              let password = String(data: data, encoding: .utf8) else {
            throw KeychainReadError.unexpectedData
        }
        return password
    case errSecItemNotFound:
        throw KeychainReadError.itemNotFound
    default:
        throw KeychainReadError.status(status)
    }
}
```

C
```c
#include <CoreFoundation/CoreFoundation.h>
#include <Security/Security.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* out_password is malloc'd UTF-8; caller free()s. Returns OSStatus. */
OSStatus keychain_copy_generic_password(
    const char *service,
    const char *account,
    char **out_password,
    UInt32 *out_length
) {
    if (!service || !account || !out_password) return errSecParam;
    *out_password = NULL;
    if (out_length) *out_length = 0;

    CFStringRef cf_service = CFStringCreateWithCString(NULL, service, kCFStringEncodingUTF8);
    CFStringRef cf_account = CFStringCreateWithCString(NULL, account, kCFStringEncodingUTF8);

    const void *keys[] = {
        kSecClass,
        kSecAttrService,
        kSecAttrAccount,
        kSecReturnData,
        kSecMatchLimit
    };
    const void *values[] = {
        kSecClassGenericPassword,
        cf_service,
        cf_account,
        kCFBooleanTrue,
        kSecMatchLimitOne
    };

    CFDictionaryRef query = CFDictionaryCreate(
        NULL, keys, values, 5,
        &kCFTypeDictionaryKeyCallBacks,
        &kCFTypeDictionaryValueCallBacks
    );

    CFTypeRef result = NULL;
    OSStatus status = SecItemCopyMatching(query, &result);

    CFRelease(query);
    CFRelease(cf_service);
    CFRelease(cf_account);

    if (status != errSecSuccess) return status;

    CFDataRef data = (CFDataRef)result;
    UInt32 len = (UInt32)CFDataGetLength(data);
    char *buf = malloc((size_t)len + 1);
    if (!buf) {
        CFRelease(result);
        return errSecAllocate;
    }
    memcpy(buf, CFDataGetBytePtr(data), len);
    buf[len] = '\0';
    CFRelease(result);

    *out_password = buf;
    if (out_length) *out_length = len;
    return errSecSuccess;
}
```

Link with `-framework Security -framework CoreFoundation`.

Notes
- Query is exact match on `kSecAttrService` + `kSecAttrAccount`. No service/account → `errSecItemNotFound`.
- Access still goes through the item ACL / user Keychain prompt. This does not bypass TCC or unlock the keychain.
- Prefer this over deprecated `SecKeychainFindGenericPassword`.
- Binary secrets: skip the UTF-8 decode and return the `Data` / bytes instead.
